// AI Agent Tool: list_files
const pattern = $input.item.json.pattern;

// Get repo context from input
const owner = $input.item.json.owner;
const repo = $input.item.json.repo;
const branch = $input.item.json.branch || 'main';

if (!owner || !repo) {
  return {
    json: {
      success: false,
      error: 'Missing repository information. Owner: ' + owner + ', Repo: ' + repo,
      files: []
    }
  };
}

if (!pattern) {
  return {
    json: {
      success: false,
      error: 'Missing file pattern',
      files: []
    }
  };
}

// Convert glob pattern to GitHub search query
let searchQuery = '';

// Extract directory path: "src/**/*.css" -> "path:src"
const pathMatch = pattern.match(/^([^*]+)/);
if (pathMatch && pathMatch[1]) {
  const cleanPath = pathMatch[1].replace(/\/$/, '');
  if (cleanPath && cleanPath !== '**') {
    searchQuery += `path:${cleanPath}`;
  }
}

// Extract file extension: "**/*.css" -> "extension:css"
const extMatch = pattern.match(/\*\.(\w+)$/);
if (extMatch) {
  if (searchQuery) searchQuery += '+';
  searchQuery += `extension:${extMatch[1]}`;
}

// Extract exact filename: "**/layout.*" -> "filename:layout"
const filenameMatch = pattern.match(/\/([^/*]+)\.(\*|\w+)$/);
if (filenameMatch && !extMatch) {
  if (searchQuery) searchQuery += '+';
  searchQuery += `filename:${filenameMatch[1]}`;
}

// If no specific pattern, search all
if (!searchQuery) {
  searchQuery = 'path:/';
}

// Build full query
const query = `repo:${owner}/${repo}+${searchQuery}`;

try {
  // Call GitHub API
  const response = await fetch(`https://api.github.com/search/code?q=${encodeURIComponent(query)}&per_page=100`, {
    headers: {
      'Authorization': `Bearer ${$env.GITHUB_TOKEN}`,
      'Accept': 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28'
    }
  });

  if (!response.ok) {
    throw new Error(`GitHub API returned ${response.status}: ${response.statusText}`);
  }

  const data = await response.json();

  // Format results
  if (!data || !data.items || data.items.length === 0) {
    return {
      json: {
        success: true,
        files: [],
        total: 0,
        pattern: pattern,
        message: `No files matching pattern '${pattern}'`,
        paths: []
      }
    };
  }

  const files = data.items.map(item => ({
    path: item.path,
    name: item.name,
    size: item.size || 0,
    url: item.html_url
  }));

  return {
    json: {
      success: true,
      files: files,
      total: data.total_count || files.length,
      pattern: pattern,
      message: `Found ${files.length} files matching '${pattern}'`,
      paths: files.map(f => f.path)
    }
  };
} catch (error) {
  return {
    json: {
      success: false,
      error: 'GitHub API error: ' + error.message,
      files: [],
      pattern: pattern,
      query: query
    }
  };
}
